package io.knowledgebrain.integration;
import java.net.*;import java.net.http.*;import java.time.*;import java.util.*;import tools.jackson.databind.*;import tools.jackson.databind.json.JsonMapper;import org.springframework.http.*;import org.springframework.web.server.ResponseStatusException;
final class GitHubClient {
 record Repository(String externalId,String fullName,String url,String defaultBranch){}
 record Commit(String sha,String subject,String authorLogin,String committedAt){}
 record Batch(Repository repository,List<Commit> commits,String headSha,boolean possiblyMore){}
 private final HttpClient http;private final URI origin;private final JsonMapper json=JsonMapper.builder().enable(DeserializationFeature.FAIL_ON_TRAILING_TOKENS).enable(tools.jackson.core.StreamReadFeature.STRICT_DUPLICATE_DETECTION).build();
 GitHubClient(){this(HttpClient.newBuilder().connectTimeout(Duration.ofSeconds(3)).followRedirects(HttpClient.Redirect.NEVER).build(),URI.create("https://api.github.com"));}
 // A separate, package-private transport seam is used by HTTPS contract tests only.
 GitHubClient(HttpClient http,URI origin){if(!"https".equals(origin.getScheme())||origin.getHost()==null||origin.getRawUserInfo()!=null||origin.getRawQuery()!=null||origin.getRawFragment()!=null||!origin.getRawPath().isEmpty()||http.followRedirects()!=HttpClient.Redirect.NEVER)throw new IllegalArgumentException("Verified HTTPS transport required");this.http=http;this.origin=origin;}
 JsonNode get(String path){try{long deadline=System.nanoTime()+Duration.ofSeconds(8).toNanos();var request=java.net.http.HttpRequest.newBuilder(origin.resolve(path)).timeout(Duration.ofSeconds(8)).header("Accept","application/vnd.github+json").header("X-GitHub-Api-Version","2026-03-10").header("User-Agent","knowledge-brain-public-integration/1").GET().build();var response=http.send(request,HttpResponse.BodyHandlers.ofInputStream());try(var in=response.body()){if(response.statusCode()==403||response.statusCode()==429)throw new ResponseStatusException(HttpStatus.SERVICE_UNAVAILABLE,"GitHub access or rate limit unavailable; retry later");if(response.statusCode()==409&&path.contains("/commits?")){byte[] empty=read(in,4097,deadline);if(empty.length<=4096&&json.readTree(empty).path("message").asString().equals("Git Repository is empty."))return json.createArrayNode();throw unavailable();}if(response.statusCode()==404||response.statusCode()==409||response.statusCode()==301||response.statusCode()==302)throw new ResponseStatusException(HttpStatus.BAD_GATEWAY,"Public GitHub repository unavailable or moved");if(response.statusCode()!=200||!response.headers().firstValue("Content-Type").orElse("").toLowerCase(Locale.ROOT).contains("json"))throw unavailable();byte[] bytes=read(in,2097153,deadline);if(bytes.length>2097152)throw unavailable();return json.readTree(bytes);}}catch(InterruptedException e){Thread.currentThread().interrupt();throw unavailable();}catch(ResponseStatusException e){throw e;}catch(Exception e){throw unavailable();}}
 Repository repository(String canonicalUrl){String checked=GitHubRules.url(canonicalUrl);var n=get("/repos/"+checked.substring("https://github.com/".length()));return repository(n,checked);}
 static Repository repository(JsonNode n,String requested){try{if(n==null||!n.isObject()||!n.path("id").isIntegralNumber()||!n.path("id").canConvertToLong()||n.path("id").asLong()<1||!n.path("private").isBoolean()||n.path("private").asBoolean()||!n.path("visibility").isString()||!n.path("visibility").asString().equals("public")||!n.path("full_name").isString()||!n.path("html_url").isString()||!n.path("default_branch").isString())throw unavailable();String name=n.path("full_name").asString(),url=GitHubRules.url(n.path("html_url").asString());if(!url.equals(requested)||!GitHubRules.url("https://github.com/"+name).equals(url))throw unavailable();String branch=GitHubRules.text(n.path("default_branch").asString(),200,true);return new Repository(Long.toString(n.path("id").asLong()),name,"https://github.com/"+name,branch);}catch(RuntimeException e){throw unavailable();}}
 Batch commits(Repository repo){var n=get("/repos/"+repo.fullName()+"/commits?per_page=20&sha="+URLEncoder.encode(repo.defaultBranch(),java.nio.charset.StandardCharsets.UTF_8));if(n==null||!n.isArray()||n.size()>20)throw unavailable();var rows=new ArrayList<Commit>();var seen=new HashSet<String>();for(var v:n){try{if(!v.path("sha").isString()||!v.path("commit").path("message").isString()||!v.path("commit").path("committer").path("date").isString())throw unavailable();String sha=GitHubRules.sha(v.path("sha").asString());if(!seen.add(sha))throw unavailable();String message=v.path("commit").path("message").asString().split("\\R",2)[0];message=message.codePoints().filter(c->!Character.isISOControl(c)&&!(c>=0xd800&&c<=0xdfff)).limit(500).collect(StringBuilder::new,StringBuilder::appendCodePoint,StringBuilder::append).toString();String author=null;if(!v.path("author").isNull()&&!v.path("author").isMissingNode()){if(!v.path("author").path("login").isString())throw unavailable();author=GitHubRules.text(v.path("author").path("login").asString(),100,true);if(!author.matches("[A-Za-z0-9-]+(?:\\[bot\\])?"))throw unavailable();}String at=Instant.parse(v.path("commit").path("committer").path("date").asString()).toString();if(at.length()>40)throw unavailable();rows.add(new Commit(sha,message,author,at));}catch(RuntimeException e){throw unavailable();}}return new Batch(repo,List.copyOf(rows),rows.isEmpty()?null:rows.getFirst().sha(),rows.size()==20);}
 // Streaming handlers return before body completion; the same total deadline
 // covers both headers and the bounded body. Closing cancels a stalled stream.
 static byte[] read(java.io.InputStream in,int bound,long deadline)throws Exception{
  var task=new java.util.concurrent.FutureTask<byte[]>(()->in.readNBytes(bound));
  Thread.ofVirtual().name("github-bounded-body").start(task);boolean completed=false;
  try{byte[] bytes=task.get(Math.max(1,deadline-System.nanoTime()),java.util.concurrent.TimeUnit.NANOSECONDS);completed=true;return bytes;}
  finally{if(!completed){task.cancel(true);in.close();}}
 }
 static ResponseStatusException unavailable(){return new ResponseStatusException(HttpStatus.BAD_GATEWAY,"GitHub response unavailable");}
}
